msg.d,
channel.label === "state" ? "state" : "reliable",
);
}
};
}
private async flushPendingCandidates(slot: PeerSlot): Promise<void> {
while (slot.pendingCandidates.length > 0) {
const candidate = slot.pendingCandidates.shift()!;
try {
await slot.pc.addIceCandidate(candidate);
} catch (err) {
if (!slot.ignoreOffer) console.warn("[p2p] addIceCandidate failed:", err);
}
if (this.closed) return;
}
}
private async onSignal(
from: string,
kind: SignalKind,
payload: unknown,
roster: Set<string>,
): Promise<void> {
if (this.closed) return;
let slot = this.peers.get(from);
if (!slot) {
if (!roster.has(from)) return;
const created = this.connectTo(from, "", false);
if (!created) return;
slot = created;
}
const polite = this.opts.selfId < from;
try {
if (kind === "offer" || kind === "answer") {
const description = payload as RTCSessionDescriptionInit;
const collision =
kind === "offer" && (slot.makingOffer || slot.pc.signalingState !== "stable");
slot.ignoreOffer = !polite && collision;
if (slot.ignoreOffer) return;
try {
await slot.pc.setRemoteDescription(description); // implicit rollback when polite
} catch (err) {
if (kind !== "offer" || slot.recreatedForOffer) throw err;
const attempts = slot.recoveryAttempts;
const name = slot.info.name;
slot.pc.close();
this.peers.delete(from);
const fresh = this.connectTo(from, name, false);
if (!fresh) return;
fresh.recoveryAttempts = attempts;
fresh.recreatedForOffer = true;
slot = fresh;
await slot.pc.setRemoteDescription(description);
}
if (this.closed) return;
await this.flushPendingCandidates(slot);
if (this.closed) return;
if (kind === "offer") {
await slot.pc.setLocalDescription();
if (this.closed) return;
await this.sendSignal(from, "answer", slot.pc.localDescription!.toJSON());
}
} else if (kind === "ice") {
const candidate = payload as RTCIceCandidateInit;
if (!slot.pc.remoteDescription) {
slot.pendingCandidates.push(candidate);
return;
}
try {
await slot.pc.addIceCandidate(candidate);
} catch (err) {
if (!slot.ignoreOffer) console.warn("[p2p] addIceCandidate failed:", err);
}
}
} catch {
}
}
private sendSignal(to: string, kind: SignalKind, payload: unknown): Promise<void> {
const prev = this.signalQueues.get(to) ?? Promise.resolve();
const next = prev.then(() => this.postSignal(to, kind, payload));
this.signalQueues.set(
to,
next.catch(() => {}),
);
return next;
}
private async postSignal(to: string, kind: SignalKind, payload: unknown): Promise<void> {
for (let attempt = 0; ; attempt++) {
if (this.closed) return;
try {
const res = await fetch("/api/rtc", {
method: "POST",
headers: { "content-type": "application/json" },
body: JSON.stringify({
op: "signal",
room: this.opts.room,
from: this.opts.selfId,
to,
kind,
payload,
}),
});
if (res.ok) return;
throw new Error(`signal POST failed: ${res.status}`);
} catch (err) {
if (attempt >= SIGNAL_RETRY_DELAYS_MS.length) {
console.warn(`[p2p] signal ${kind} to ${to} failed after retries`, err);
return;
}
await new Promise((r) => setTimeout(r, SIGNAL_RETRY_DELAYS_MS[attempt]));
}
}
}
private pingAll(): void {
const wire = JSON.stringify({ t: "ping" });
for (const slot of this.peers.values()) {
if (slot.state?.readyState !== "open") continue;
const stale =
slot.pingSentAt !== undefined && performance.now() - slot.pingSentAt > 2 * PING_INTERVAL_MS;
if (slot.pingSentAt === undefined || stale) {
slot.pingSentAt = performance.now();
slot.state.send(wire);
}
}
}
private watchdog(): void {
if (this.closed) return;
const now = Date.now();
for (const [peerId, slot] of this.peers) {
const live = slot.pc.connectionState;
if (live !== slot.info.connectionState) {
slot.info.connectionState = live;
if (live === "connecting" || live === "connected") slot.lastProgressAt = now;
this.emitPeers();
}
if (slot.terminal || live === "connected") continue;
if (now - slot.lastProgressAt <= STALL_MS) continue;
if (slot.recoveryAttempts >= MAX_RECOVERY_ATTEMPTS) {
slot.terminal = true;
this.emitPeers();
continue;
}
slot.recoveryAttempts += 1;
slot.lastProgressAt = now; // re-arm the stall window
if (this.opts.selfId > peerId) {
const { name } = slot.info;
const attempts = slot.recoveryAttempts;
slot.pc.close();
this.peers.delete(peerId);
const fresh = this.connectTo(peerId, name, true);
if (fresh) fresh.recoveryAttempts = attempts;
this.schedulePoll(FAST_POLL_MS);
}
}
}
private async readCandidateType(slot: PeerSlot): Promise<void> {
try {
const stats = await slot.pc.getStats();
let selected: RTCIceCandidatePairStats | undefined;
stats.forEach((s) => {
if (s.type === "candidate-pair" && (s as RTCIceCandidatePairStats).nominated) {
selected = s as RTCIceCandidatePairStats;
}
});
const localId = selected?.localCandidateId;
if (localId) {
const local = stats.get(localId) as { candidateType?: string } | undefined;
slot.info.candidateType = local?.candidateType ?? null;
this.emitPeers();
}
} catch {
}
}
private emitPeers(): void {
const list = this.peerList();
const fingerprint = JSON.stringify(
list.map((p) => [p.id, p.name, p.connectionState, p.candidateType, p.rttMs]),
);
if (fingerprint === this.lastPeersFingerprint) return;
this.lastPeersFingerprint = fingerprint;
this.opts.onPeersChanged?.(list);
}
}

import { z } from "zod";
import { getSql, type Sql } from "@/lib/db";
import type { PeerRow, RtcPollResponse, SignalRow } from "./p2p";
const ID = z.string().regex(/^[a-zA-Z0-9_-]{1,64}$/);
const signalSchema = z.object({
op: z.literal("signal"),
room: ID,
from: ID,
to: ID,
kind: z.enum(["offer", "answer", "ice"]),
payload: z.unknown().refine((v) => v !== undefined && JSON.stringify(v).length <= 32_768, {
message: "payload too large",
}),
});
const leaveSchema = z.object({ op: z.literal("leave"), room: ID, peer: ID });
const postSchema = z.discriminatedUnion("op", [signalSchema, leaveSchema]);
const PEER_TTL_SECONDS = 30;
const SIGNAL_TTL_SECONDS = 60;
const globalRef = globalThis as typeof globalThis & {
__rtcSchemaPromise__?: Promise<void>;
};
function ensureSchema(sql: Sql): Promise<void> {
globalRef.__rtcSchemaPromise__ ??= (async () => {
await sql.query(
`CREATE TABLE IF NOT EXISTS webrtc_peers (
room TEXT NOT NULL,
peer_id TEXT NOT NULL,
name TEXT NOT NULL DEFAULT '',
last_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
PRIMARY KEY (room, peer_id)
)`,
);
await sql.query(
`CREATE TABLE IF NOT EXISTS webrtc_signals (
id BIGSERIAL PRIMARY KEY,
room TEXT NOT NULL,
to_peer TEXT NOT NULL,
from_peer TEXT NOT NULL,
kind TEXT NOT NULL,
payload JSONB NOT NULL,
created_at TIMESTAMPTZ NOT NULL DEFAULT now()
)`,
);
await sql.query(
`CREATE INDEX IF NOT EXISTS webrtc_signals_inbox
ON webrtc_signals (room, to_peer, id)`,
);
})().catch((err) => {
globalRef.__rtcSchemaPromise__ = undefined;
throw err;
});
return globalRef.__rtcSchemaPromise__;
}
async function roster(sql: Sql, room: string): Promise<PeerRow[]> {
const rows = await sql.query<{ peer_id: string; name: string }>(
`SELECT peer_id, name FROM webrtc_peers
WHERE room = $1 AND last_seen > now() - make_interval(secs => $2)
ORDER BY peer_id LIMIT 32`,
[room, PEER_TTL_SECONDS],
);
return rows.map((r) => ({ id: r.peer_id, name: r.name }));
}
async function touchPeer(sql: Sql, room: string, peer: string, name: string) {
await sql.query(
`INSERT INTO webrtc_peers (room, peer_id, name, last_seen)
VALUES ($1, $2, $3, now())
ON CONFLICT (room, peer_id)
DO UPDATE SET last_seen = now(), name = EXCLUDED.name`,
[room, peer, name],
);
}
async function prune(sql: Sql) {
await Promise.all([
sql.query(`DELETE FROM webrtc_signals WHERE created_at < now() - make_interval(secs => $1)`, [
SIGNAL_TTL_SECONDS,
]),
sql.query(`DELETE FROM webrtc_peers WHERE last_seen < now() - make_interval(secs => $1)`, [
PEER_TTL_SECONDS,
]),
]);
}
function json(body: unknown, status = 200): Response {
return new Response(JSON.stringify(body), {
status,
headers: { "content-type": "application/json", "cache-control": "no-store" },
});
}
async function handleGet(url: URL): Promise<Response> {
const parsed = z
.object({
room: ID,
peer: ID,
name: z.string().max(64).default(""),
since: z.coerce.number().int().min(0).default(0),
})
.safeParse({
room: url.searchParams.get("room"),
peer: url.searchParams.get("peer"),
name: url.searchParams.get("name") ?? "",
since: url.searchParams.get("since") ?? 0,
});
if (!parsed.success) return json({ error: "invalid query" }, 400);
const { room, peer, name, since } = parsed.data;
const sql = await getSql();
await ensureSchema(sql);
if (since === 0 || Math.random() < 0.02) await prune(sql);
await touchPeer(sql, room, peer, name);
const rows = await sql.query<{
id: number;
from_peer: string;
kind: SignalRow["kind"];
payload: unknown;
}>(
`SELECT id, from_peer, kind, payload FROM webrtc_signals
WHERE room = $1 AND to_peer = $2 AND id > $3
ORDER BY id LIMIT 200`,
[room, peer, since],
);
const body: RtcPollResponse = {
peers: await roster(sql, room),
signals: rows.map((r) => ({
id: r.id,
from: r.from_peer,
kind: r.kind,
payload: r.payload,
})),
};
return json(body);
}
async function handlePost(request: Request): Promise<Response> {
let body: unknown;
try {
body = await request.json();
} catch {
return json({ error: "invalid JSON" }, 400);
}
const parsed = postSchema.safeParse(body);
if (!parsed.success) return json({ error: "invalid request" }, 400);
const msg = parsed.data;
const sql = await getSql();
await ensureSchema(sql);
if (msg.op === "signal") {
await sql.query(
`INSERT INTO webrtc_signals (room, to_peer, from_peer, kind, payload)
VALUES ($1, $2, $3, $4, $5)`,
[msg.room, msg.to, msg.from, msg.kind, JSON.stringify(msg.payload)],
);
} else {
await sql.query(`DELETE FROM webrtc_peers WHERE room = $1 AND peer_id = $2`, [
msg.room,
msg.peer,
]);
}
return json({ ok: true });
}
export async function handleSignaling(request: Request): Promise<Response> {
try {
if (request.method === "GET") return await handleGet(new URL(request.url));
if (request.method === "POST") return await handlePost(request);
return json({ error: "method not allowed" }, 405);
} catch (error) {
console.error("[rtc] signaling error:", error);
return json({ error: "signaling failed" }, 500);
}
}

import { useCallback, useEffect, useRef, useState } from "react";
import { P2PRoom, type PeerInfo } from "./p2p";
export interface UseP2PRoomOptions {
room: string;
name?: string;
enabled?: boolean;
}
export interface P2PRoomHandle {
selfId: string;
room: string;
peers: PeerInfo[];
joined: boolean;
broadcast: (data: unknown) => void;
send: (data: unknown, peerId?: string) => void;
onMessage: (
fn: (from: string, data: unknown, channel: "state" | "reliable") => void,
) => () => void;
}
export function useP2PRoom(options: UseP2PRoomOptions): P2PRoomHandle {
const [selfId] = useState(() => `p-${Math.random().toString(36).slice(2, 10)}`);
const [room] = useState(() => options.room);
const [name] = useState(() => options.name ?? selfId);
const enabled = options.enabled !== false;
const [peers, setPeers] = useState<PeerInfo[]>([]);
const [joined, setJoined] = useState(false);
const roomRef = useRef<P2PRoom | null>(null);
const listeners = useRef(
new Set<(from: string, data: unknown, channel: "state" | "reliable") => void>(),
);
useEffect(() => {
if (!enabled) return;
const p2p = new P2PRoom({
room,
selfId,
name,
onPeersChanged: setPeers,
onMessage: (from, data, channel) => {
for (const fn of listeners.current) fn(from, data, channel);
},
onConnected: () => setJoined(true),
});
roomRef.current = p2p;
void p2p.join();
return () => {
roomRef.current = null;
p2p.close();
setJoined(false);
setPeers([]);
};
}, [room, selfId, name, enabled]);
const broadcast = useCallback((data: unknown) => roomRef.current?.broadcast(data), []);
const send = useCallback(
(data: unknown, peerId?: string) => roomRef.current?.send(data, peerId),
[],
);
const onMessage = useCallback(
(fn: (from: string, data: unknown, channel: "state" | "reliable") => void) => {
listeners.current.add(fn);
return () => {
listeners.current.delete(fn);
};
},
[],
);
return { selfId, room, peers, joined, broadcast, send, onMessage };
}

export type DeliveryMode = "corrected" | "voice" | "both";
export type WireMsg =
| {
v: 1;
type: "cutin";
id: string;
fromName: string;
text: string;
mode: DeliveryMode;
audioBase64?: string;
audioMime?: string;
ts: number;
}
| {
v: 1;
type: "ack";
id: string;
fromName: string;
}
| {
v: 1;
type: "presence";
name: string;
};
export interface ThreadItem {
id: string;
direction: "out" | "in";
fromName: string;
text: string;
mode: DeliveryMode;
ts: number;
status: "sending" | "sent" | "delivered" | "failed" | "playing" | "played";
hasAudio: boolean;
}
export interface DraftMessage {
text: string;
audioBase64?: string;
audioMime?: string;
mode: DeliveryMode;
durationMs: number;
}
export function isWireMsg(data: unknown): data is WireMsg {
if (!data || typeof data !== "object") return false;
const m = data as { v?: unknown; type?: unknown };
return m.v === 1 && typeof m.type === "string";
}
export function makeRoomCode(): string {
const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
let out = "";
const bytes = new Uint8Array(6);
crypto.getRandomValues(bytes);
for (let i = 0; i < 6; i += 1) out += alphabet[bytes[i]! % alphabet.length];
return out;
}
export function roomIdFromCode(code: string): string {
return `ct-${code.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 8)}`;
}
export function normalizeRoomCode(raw: string): string {
return raw.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 8);
}

